@startuml

class AlphaInsurance {
  + companyName : string
}

class Customer {
  + name : string
  + address : string
  + customerId : int
}

class Broker {
  + brokerId : int
  + name : string
}

class Contract {
  + contractId : int
  + signingDate : date
  + billingFrequency : string
  + price : float
}

abstract class InsurancePolicy {
  + policyType : string
}

class LifePolicy {}
class CarPolicy {}
class RiskPolicy {}

class Offer {
  + offerId : int
  + status : string
  + deliveryMethod : string
}

class ClaimCase {
  + caseId : int
  + description : string
  + status : string
}

class Estimator {
  + estimatorId : int
  + areaOfExpertise : string
}

class EstimatorReport {
  + reportId : int
  + findings : string
  + reportDate : date
}

class CompensationDecision {
  + decisionId : int
  + eligibleCosts : float
  + isApproved : boolean
}

class Payment {
  + paymentId : int
  + amount : float
  + paymentDate : date
}

AlphaInsurance "1" *-- "*" Customer
Broker "1" -- "*" Customer
Customer "1" -- "*" Contract
Contract "1" -- "1" InsurancePolicy
InsurancePolicy --|> Policy
LifePolicy --|> InsurancePolicy
CarPolicy --|> InsurancePolicy
RiskPolicy --|> InsurancePolicy

Customer "1" -- "*" Offer
Offer "0..1" -- "0..1" Contract

Contract "1" -- "*" ClaimCase
ClaimCase "1" -- "*" EstimatorReport
Estimator "1" -- "*" EstimatorReport
EstimatorReport "*" -- "0..1" CompensationDecision
CompensationDecision "1" -- "1" Payment
Payment "*" -- "1" Customer

@enduml

